    "src/interfaces/IEtherFiDataProvider.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { IRoleRegistry } from "./IRoleRegistry.sol";

/**
 * @title IEtherFiDataProvider
 * @author ether.fi
 * @notice Interface for the EtherFiDataProvider contract that manages important data for ether.fi
 */
interface IEtherFiDataProvider {
    /**
     * @notice Configures multiple modules' whitelist status
     * @dev Only callable by addresses with ADMIN_ROLE
     * @param modules Array of module addresses to configure
     * @param shouldWhitelist Array of boolean values indicating whether each module should be whitelisted
     */
    function configureModules(address[] calldata modules, bool[] calldata shouldWhitelist) external;

    /**
     * @notice Updates the hook address
     * @dev Only callable by addresses with ADMIN_ROLE
     * @param hook New hook address to set
     */
    function setHookAddress(address hook) external;

    /**
     * @notice Updates the address of the Cash Module
     * @dev Only callable by addresses with ADMIN_ROLE
     * @param cashModule New cash module address to set
     */
    function setCashModule(address cashModule) external;

    /**
     * @notice Whether the data provider is paused
     * @dev Inherited from UpgradeableProxy's PausableUpgradeable and toggled by the RoleRegistry
     *      pauser/unpauser roles. EtherFiSafe reads it as the kill switch for ETH wrapping.
     * @return bool True if paused, false otherwise
     */
    function paused() external view returns (bool);

    /**
     * @notice Checks if a module address is whitelisted
     * @param module Address to check
     * @return bool True if the module is whitelisted, false otherwise
     */
    function isWhitelistedModule(address module) external view returns (bool);

    /**
     * @notice Checks if a module address is a whitelisted default module
     * @param module Address to check
     * @return bool True if the module is a whitelisted default module, false otherwise
     */
    function isDefaultModule(address module) external view returns (bool);

    /**
     * @notice Retrieves all whitelisted module addresses
     * @return address[] Array of whitelisted module addresses
     */
    function getWhitelistedModules() external view returns (address[] memory);

    /**
     * @notice Returns the address of the Cash Module
     * @return Address of the cash module
     */
    function getCashModule() external view returns (address);

    /**
     * @notice Returns the address of the EtherFi Recovery signer
     * @return Address of the EtherFi Recovery Signer
     */
    function getEtherFiRecoverySigner() external view returns (address);

     /**
     * @notice Returns the address of the Third Party Recovery signer
     * @return Address of the Third Party Recovery Signer
     */
    function getThirdPartyRecoverySigner() external view returns (address);

        /**
     * @notice Returns the address of the Refund wallet
     * @return Address of the Refund wallet
     */
    function getRefundWallet() external view returns (address);

    /**
     * @notice Returns the Recovery delay period in seconds
     * @return Recovery delay period in seconds
     */
    function getRecoveryDelayPeriod() external view returns (uint256);

    /**
     * @notice Returns the address of the Cash Lens contract
     * @return Address of the Cash Lens contract
     */
    function getCashLens() external view returns (address);

    /**
     * @notice Returns the address of the Price provider contract
     * @return Address of the Price provider contract
     */
    function getPriceProvider() external view returns (address);

    /**
     * @notice Returns the current hook address
     * @return address Current hook address
     */
    function getHookAddress() external view returns (address);

    function getEtherFiSafeFactory() external view returns (address);

    /**
     * @notice Function to check if an account is an EtherFiSafe
     * @param account Address of the account to check
     */
    function isEtherFiSafe(address account) external view returns (bool);

    /**
     * @notice Role identifier for administrative privileges
     * @return bytes32 The keccak256 hash of "ADMIN_ROLE"
     */
    function ADMIN_ROLE() external view returns (bytes32);

    /**
     * @notice Returns the address of the Role Registry contract
     * @return roleRegistry Reference to the role registry contract
     */
    function roleRegistry() external view returns (IRoleRegistry);
}
"
    },
    "src/interfaces/IEtherFiSafe.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IEtherFiSafe {
    /**
     * @notice Verifies signatures against a digest hash until reaching the required threshold
     * @param digestHash The hash of the data that was signed
     * @param signers Array of addresses that supposedly signed the message
     * @param signatures Array of signatures corresponding to the signers
     * @return bool True if enough valid signatures are found to meet the threshold
     * @dev Processes signatures until threshold is met. Invalid signatures are skipped.
     * @custom:throws EmptySigners If the signers array is empty
     * @custom:throws ArrayLengthMismatch If the lengths of signers and signatures arrays do not match
     * @custom:throws InsufficientSigners If the length of signers array is less than the required threshold
     * @custom:throws DuplicateElementFound If the signers array contains duplicate addresses
     * @custom:throws InvalidSigner If a signer is the zero address or not an owner of the safe
     */
    function checkSignatures(bytes32 digestHash, address[] calldata signers, bytes[] calldata signatures) external view returns (bool);

    /**
     * @notice Executes a transaction from an authorized module
     * @dev Allows modules to execute arbitrary transactions on behalf of the safe
     * @param to Array of target addresses for the calls
     * @param values Array of ETH values to send with each call
     * @param data Array of calldata for each call
     * @custom:throws OnlyModules If the caller is not an enabled module
     * @custom:throws CallFailed If any of the calls fail
     */
    function execTransactionFromModule(address[] calldata to, uint256[] calldata values, bytes[] calldata data) external;

    /**
     * @notice Gets the current nonce value
     * @dev Used for replay protection in signatures
     * @return Current nonce value
     */
    function nonce() external view returns (uint256);

    /**
     * @notice Returns all current owners of the safe
     * @dev Implementation of the abstract function from ModuleManager
     * @return address[] Array containing all owner addresses
     */
    function getOwners() external view returns (address[] memory);

    /**
     * @notice Uses a nonce for operations in modules which require a quorum of owners
     * @dev Can only be called by enabled modules
     * @return uint256 The current nonce value before incrementing
     * @custom:throws OnlyModules If the caller is not an enabled module
     */
    function useNonce() external returns (uint256);

    function isAdmin(address account) external view returns (bool); 
}
"
    },
    "src/interfaces/ILendGateway.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title ILendGateway
 * @notice Seam between the Cash contracts and the ether.fi-managed Aave v4 instance. The gateway
 *         acts as a safe's Aave position manager, performing supply / withdraw / borrow / repay on
 *         the safe's behalf (a card spend cannot wait for a user signature). Cash-side contracts
 *         (CashModule, CashLens, EtherFiHook) depend only on this interface; both the live gateway
 *         and a MockLendGateway satisfy it, so the two tracks can build in parallel.
 * @dev v0 — expected to change. Locked to just enough surface to unblock both tracks. Borrow and
 *      withdraw take an explicit `to` because Aave pays the caller; the caller forwards atomically.
 * @author ether.fi
 */
interface ILendGateway {
    /// @notice A safe's Aave position summary. USD fields are 6 decimals (matching PriceProvider.DECIMALS); healthFactor is 1e18.
    struct AccountData {
        uint256 collateralUsd;
        uint256 debtUsd;
        // borrowing headroom: collateral weighted by each reserve's LTV, minus debt
        uint256 availableBorrowsUsd;
        // gross borrowing power: collateral weighted by each reserve's LTV, NOT reduced by debt and never
        // clamped, so a value below debtUsd both signals and measures an over-LTV position
        uint256 maxBorrowUsd;
        uint256 healthFactor;
    }

    /**
     * @notice Supplies `amount` of `asset` to Aave on behalf of `safe` and enables it as collateral
     * @dev Supply and collateral enablement are atomic: either both succeed or neither does.
     * @param safe The safe whose position is credited
     * @param asset The asset being supplied
     * @param amount The amount to supply
     */
    function supply(address safe, address asset, uint256 amount) external;

    /**
     * @notice Withdraws `amount` of `asset` from `safe`'s Aave position to `to`
     * @param safe The safe whose position is debited
     * @param asset The asset being withdrawn
     * @param amount The amount to withdraw
     * @param to The recipient of the withdrawn asset
     */
    function withdraw(address safe, address asset, uint256 amount, address to) external;

    /**
     * @notice Borrows `amount` of `asset` against `safe`'s position and sends it to `to`
     * @param safe The safe whose position takes on the debt
     * @param asset The asset being borrowed
     * @param amount The amount to borrow
     * @param to The recipient of the borrowed asset
     */
    function borrow(address safe, address asset, uint256 amount, address to) external;

    /**
     * @notice Repays `amount` of `asset` debt on behalf of `safe`
     * @param safe The safe whose debt is repaid
     * @param asset The asset being repaid
     * @param amount The amount to repay; use type(uint256).max to repay the full debt
     * @return The actual amount repaid
     */
    function repay(address safe, address asset, uint256 amount) external returns (uint256);

    /**
     * @notice Toggles whether `safe`'s supplied `asset` counts as collateral
     * @param safe The safe whose position is updated
     * @param asset The supplied asset
     * @param useAsCollateral True to use as collateral, false to disable
     */
    function setUsingAsCollateral(address safe, address asset, bool useAsCollateral) external;

    /**
     * @notice Returns `safe`'s Cash-priced position summary
     * @dev Used for display and debit sizing; credit authorization uses borrowCapacity.
     * @param safe The safe to query
     * @return The safe's account data
     */
    function getAccountData(address safe) external view returns (AccountData memory);

    /**
     * @notice Whether the safe carries any raw debt on Aave (raw per-asset reads, immune to the
     *         6-decimal flooring of getAccountData's debtUsd)
     * @param safe The safe to check
     * @return True when any registered asset carries debt for the safe
     */
    function hasDebt(address safe) external view returns (bool);

    /**
     * @notice The post-op health-factor floor (WAD) for user-extraction ops; 0 = disabled
     * @return The floor in WAD
     */
    function minHealthFactor() external view returns (uint256);

    /**
     * @notice Reverts HealthFactorBelowMinimum when the floor is set and `safe`'s health factor is below it
     * @dev Extraction paths (borrow page, withdrawal sourcing, collateral flag off, risk-increasing module
     *      flows) call this post-op; spends and repays are deliberately exempt.
     * @param safe The safe to check
     */
    function ensureMinHealthFactor(address safe) external view;

    /**
     * @notice Returns `safe`'s current Aave health factor in WAD (1e18), unbounded when it carries no debt
     * @param safe The safe to query
     * @return The health factor in WAD
     */
    function healthFactor(address safe) external view returns (uint256);

    /**
     * @notice Enforces the floor as "no worse off": passes when the operation did not degrade `safe`'s health,
     *         otherwise requires the end state to hold the configured floor
     * @dev Lets a position already below the floor still run health-neutral or de-risking operations, which a
     *      plain end-state floor check would block. Callers capture the health factor before the operation.
     * @param safe The safe to check
     * @param healthFactorBefore The safe's health factor captured before the operation ran
     */
    function ensureMinHealthFactorNotWorsened(address safe, uint256 healthFactorBefore) external view;

    /**
     * @notice Sets the post-op health-factor floor
     * @param value The floor in WAD; 0 disables, otherwise bounded to [1e18, 2e18]
     */
    function setMinHealthFactor(uint256 value) external;

    /**
     * @notice Returns the amount of `asset` that `safe` has supplied to Aave
     * @param safe The safe to query
     * @param asset The supplied asset
     * @return The supplied amount, in asset units
     */
    function suppliedOf(address safe, address asset) external view returns (uint256);

    /**
     * @notice Returns the amount of `asset` debt that `safe` owes Aave
     * @param safe The safe to query
     * @param asset The borrowed asset
     * @return The debt amount, in asset units
     */
    function debtOf(address safe, address asset) external view returns (uint256);

    /**
     * @notice Returns the reserve-level Hub liquidity currently available for withdrawals
     * @dev This is not a Safe's withdrawal limit, which also depends on its supply and position health. A
     *      borrow is additionally bounded by the Hub's drawCap, so use borrowLiquidity for the credit side.
     * @param asset The reserve asset
     * @return The available liquidity, in asset units
     */
    function withdrawalLiquidity(address asset) external view returns (uint256);

    /**
     * @notice Returns the reserve-level Hub liquidity currently available for borrowing
     * @dev This is not a Safe's borrowing limit, which also depends on its collateral and position health. It
     *      is the lesser of shared Hub liquidity and remaining drawCap after debt, premium, and deficit, and is
     *      zero unless the reserve and Hub Spoke accept borrowing.
     * @param asset The reserve asset
     * @return The borrowable amount, in asset units
     */
    function borrowLiquidity(address asset) external view returns (uint256);

    /**
     * @notice Returns the amount of `asset` the Spoke can currently accept as new supply
     * @dev Zero while the reserve is paused or frozen or its Hub Spoke is inactive or halted;
     *      type(uint256).max when the addCap is the uncapped sentinel, otherwise the remaining cap room.
     * @param asset The reserve asset
     * @return The suppliable amount in asset units, or 0 if the asset is not registered
     */
    function supplyHeadroom(address asset) external view returns (uint256);

    /**
     * @notice Returns `safe`'s buffered Aave-priced borrowing capacity in units of `asset`
     * @dev The auth quote: capacity holding the post-borrow health factor at or above the configured floor
     *      (Aave's 1.00 bound while no floor is set). Uses Aave's current oracle, collateral factors, debt
     *      indices, and premium. Capacity rounds down. Excludes Hub liquidity and draw caps (see borrowLiquidity).
     * @param safe The Safe whose position backs the borrow
     * @param asset The asset to borrow
     * @return The maximum additional borrow in asset units
     */
    function borrowCapacity(address safe, address asset) external view returns (uint256);

    /**
     * @notice Returns `safe`'s Aave-priced borrowing capacity in units of `asset` at Aave's 1.00 health factor
     * @dev The execution quote: what an already-authorized card spend can still borrow, ignoring the configured
     *      floor. Spend-time resupply gates on this so a spend authorized under borrowCapacity always lands.
     * @param safe The Safe whose position backs the borrow
     * @param asset The asset to borrow
     * @return The maximum additional borrow in asset units
     */
    function rawBorrowCapacity(address safe, address asset) external view returns (uint256);

    /**
     * @notice Returns `safe`'s Aave-priced collateral headroom above the configured health-factor floor
     * @dev The auth quote for collateral withdrawals, in the weighted collateral value unit
     *      (amount * aavePrice * 10^(18 - decimals) * collateralFactorBps). Execution reads
     *      rawWithdrawHeadroom, mirroring the borrowCapacity/rawBorrowCapacity pair.
     * @param safe The Safe whose position is measured
     * @return The headroom in weighted collateral value units
     */
    function withdrawHeadroom(address safe) external view returns (uint256);

    /**
     * @notice Returns `safe`'s Aave-priced collateral headroom above Aave's 1.00 health-factor bound
     * @dev The execution quote: what an already-authorized debit settlement or repay sizing may consume.
     * @param safe The Safe whose position is measured
     * @return The headroom in weighted collateral value units
     */
    function rawWithdrawHeadroom(address safe) external view returns (uint256);

    /**
     * @notice Returns the weighted collateral value `safe`'s position is short of Aave's 1.00 bound
     * @dev The unclamped complement of rawWithdrawHeadroom: non-zero only while a price move holds the
     *      position under 1.00 pre-liquidation. Sizing paths that must pass Aave's whole-position check
     *      (credit resupply, the repay-withdraw leg) add this so an existing deficit is covered up front.
     * @param safe The Safe whose position is measured
     * @return The deficit in weighted collateral value units, 0 while healthy
     */
    function deficitValue(address safe) external view returns (uint256);

    /**
     * @notice Amount of `asset` the safe can withdraw from Aave while consuming at most `headroom`
     * @dev Supply carrying no borrowing power (collateral flag off or zero collateral factor) is fully
     *      withdrawable, matching Aave's own check. Rounds down, so withdrawing the quote never breaches
     *      the headroom under Aave's own share rounding.
     * @param safe The Safe whose position is measured
     * @param asset The supplied asset
     * @param headroom The weighted collateral value the withdrawal may consume
     * @return The withdrawable amount in asset units, or 0 if the asset is unregistered
     */
    function collateralForHeadroom(address safe, address asset, uint256 headroom) external view returns (uint256);

    /**
     * @notice The weighted collateral value withdrawing `amount` of `asset` consumes
     * @dev Exact against Aave's own share revaluation, so threading it across tokens never under-counts.
     * @param safe The Safe whose position is measured
     * @param asset The supplied asset (must be registered)
     * @param amount The withdrawal in asset units
     * @return The consumed weighted collateral value
     */
    function headroomRemoved(address safe, address asset, uint256 amount) external view returns (uint256);

    /**
     * @notice The weighted collateral value a borrow of `amount` of `asset` requires at Aave's 1.00 bound
     * @dev The value a repay frees is repayValue, which follows Aave's restore rounding instead.
     * @param asset The borrow asset (must be registered)
     * @param amount The borrow in asset units
     * @return The required weighted collateral value
     */
    function borrowValue(address asset, uint256 amount) external view returns (uint256);

    /**
     * @notice The weighted collateral value a repay of `amount` of `asset` frees at Aave's 1.00 bound
     * @dev Exact against Aave's restore share rounding (premium clears first, drawn shares restore rounded
     *      down), so repay sizing can credit it as headroom without overshooting Aave's post-withdraw
     *      health check.
     * @param safe The Safe whose debt is repaid
     * @param asset The repaid asset (must be registered)
     * @param amount The repay in asset units
     * @return The freed weighted collateral value
     */
    function repayValue(address safe, address asset, uint256 amount) external view returns (uint256);

    /**
     * @notice Amount of `asset` to supply so the position gains `value` of weighted collateral value
     * @dev Rounded up. Caller guarantees the reserve's collateral factor is nonzero (see ltv).
     * @param asset The collateral asset (must be registered)
     * @param value The weighted collateral value to gain
     * @return The amount to supply in asset units
     */
    function collateralForValue(address asset, uint256 value) external view returns (uint256);

    /**
     * @notice Returns the loan-to-value of `asset`'s reserve, in the 100e18 = 100% scale (matching DebtManager's CollateralTokenConfig.ltv)
     * @param asset The reserve asset
     * @return The LTV, where 100e18 is 100%
     */
    function ltv(address asset) external view returns (uint256);

    /**
     * @notice Returns whether `asset` is a registered reserve on the gateway
     * @dev A sandwich re-supplies its output only when the asset is registered; an unregistered output
     *      (a swap into a non-collateral token, an unlisted Liquid receipt) stays loose in the safe.
     * @param asset The asset to query
     * @return True if the asset has a registered reserveId
     */
    function isRegistered(address asset) external view returns (bool);

    /**
     * @notice Returns the assets registered on the gateway (each mapped to an Aave reserveId)
     * @dev The authoritative list of assets a safe can have a position in, keyed on the gateway rather than
     *      DebtManager's collateral list (which can be delisted while an Aave position is still open).
     * @return The registered asset addresses
     */
    function registeredAssets() external view returns (address[] memory);

    /**
     * @notice Returns whether `asset` is registered and its Aave reserve accepts a borrow
     * @dev Mirrors Aave's borrow gate (borrowable, not frozen, not paused). The paths that create new
     *      debt gate on this: the credit auth check, the credit spend, and the signed borrow. Debit
     *      spends gate on isSpendAsset and repay gates on isRegistered, so existing positions survive a
     *      freeze or delisting of new debt.
     * @param asset The asset to query
     * @return True if the asset is registered and the reserve accepts a borrow
     */
    function isBorrowable(address asset) external view returns (bool);

    /**
     * @notice Returns the registered assets whose Aave reserves accept a borrow
     * @dev The gateway-native replacement for DebtManager's getBorrowTokens (see isBorrowable).
     * @return The borrowable asset addresses
     */
    function borrowableAssets() external view returns (address[] memory);

    /**
     * @notice Returns whether `asset` is an admin-declared card settlement token
     * @dev Static membership (via setSpendAsset, always a registered reserve), read from neither Aave's
     *      borrowable flag — so a supply-only reserve can be spendable — nor its execution state. A debit
     *      spend transfers loose balance and withdraws supplied balance, so one funded entirely from loose
     *      balance needs nothing from Aave; a freeze is irrelevant and a pause costs only the supplied leg,
     *      which withdrawalLiquidity already reports as zero (audit I-02). Credit gates on isBorrowable.
     * @param asset The asset to query
     * @return True if the asset is a declared card settlement token
     */
    function isSpendAsset(address asset) external view returns (bool);

    /**
     * @notice Returns the admin-declared card settlement tokens
     * @dev See isSpendAsset: membership, not Aave state.
     * @return The declared spend asset addresses
     */
    function spendAssets() external view returns (address[] memory);
}
"
    },
    "src/libraries/ArrayDeDupLib.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title ArrayDeDupLib
 * @author ether.fi
 * @notice Library for checking and handling duplicate elements in arrays
 * @dev Provides utility functions to verify array uniqueness
 */
library ArrayDeDupLib {
    /**
     * @notice Thrown when a duplicate element is found in an array that requires unique elements
     */
    error DuplicateElementFound();

    /**
     * @notice Checks if an array of addresses contains duplicate elements
     * @dev Uses an O(n²) algorithm that's efficient for small arrays
     * @param addresses Array of addresses to check for duplicates
     * @custom:throws DuplicateElementFound If a duplicate address is found in the array
     */
    function checkDuplicates(address[] memory addresses) internal pure {
        uint256 length = addresses.length;
        if (length <= 1) return;

        address[] memory seen = new address[](length);

        for (uint256 i = 0; i < length;) {
            address current = addresses[i];

            for (uint256 j = 0; j < i;) {
                if (current == seen[j]) revert DuplicateElementFound();
                unchecked {
                    ++j;
                }
            }

            seen[i] = current;
            unchecked {
                ++i;
            }
        }
    }
}"
    },
    "src/libraries/CashVerificationLib.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import { IERC20, SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { MessageHashUtils } from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

import { Mode } from "../interfaces/ICashModule.sol";
import { IEtherFiSafe } from "../interfaces/IEtherFiSafe.sol";
import { SignatureUtils } from "./SignatureUtils.sol";

/**
 * @title CashVerificationLib
 * @notice Library providing signature verification functionality for Cash operations
 * @dev Uses SignatureUtils and MessageHashUtils for ECDSA signature verification
 * @author ether.fi
 */
library CashVerificationLib {
    using SignatureUtils for bytes32;
    using MessageHashUtils for bytes32;

    /// @notice Method identifier for withdrawal requests
    bytes32 public constant REQUEST_WITHDRAWAL_METHOD = keccak256("requestWithdrawal");

    /// @notice Method identifier for withdrawal cancellation
    bytes32 public constant CANCEL_WITHDRAWAL_METHOD = keccak256("cancelWithdrawal");

    /// @notice Method identifier for spending limit updates
    bytes32 public constant UPDATE_SPENDING_LIMIT_METHOD = keccak256("updateSpendingLimit");

    /// @notice Method identifier for mode changes
    bytes32 public constant SET_MODE_METHOD = keccak256("setMode");

    /// @notice Method identifier for cashback split changes for a safe
    bytes32 public constant SET_CASHBACK_SPLIT_TO_SAFE_PERCENTAGE = keccak256("setCashbackSplitToSafePercentage");

    /// @notice Method identifier for toggling lend participation (opt in/out of Aave)
    bytes32 public constant TOGGLE_LEND_METHOD = keccak256("toggleLend");

    /// @notice Method identifier for borrowing against the safe's lend-market position
    bytes32 public constant BORROW_METHOD = keccak256("borrow");

    /// @notice Error for Invalid Owner quorum signatures
    error InvalidSignatures();

    /**
     * @notice Verifies the signature for a method
     * @param safe Address of the safe
     * @param signer Address of the signer to verify against
     * @param methodHash Method hash for the method called
     * @param nonce Transaction nonce for replay protection
     * @param encodedData Encoded data for the operation
     * @param signature ECDSA signature bytes
     * @custom:throws SignatureUtils.InvalidSignature if the signature is invalid
     */
    function verifySignature(address safe, address signer, bytes32 methodHash, uint256 nonce, bytes memory encodedData, bytes calldata signature) internal view {
        bytes32 digestHash = keccak256(abi.encodePacked(methodHash, block.chainid, safe, nonce, encodedData)).toEthSignedMessageHash();
        digestHash.checkSignature(signer, signature);
    }

    /**
     * @notice Verifies a signature for changing the cash mode
     * @dev Creates and validates an EIP-191 signed message hash
     * @param safe Address of the safe
     * @param signer Address of the signer to verify against
     * @param nonce Transaction nonce for replay protection
     * @param mode New cash mode (Credit or Debit)
     * @param signature ECDSA signature bytes
     * @custom:throws SignatureUtils.InvalidSignature if the signature is invalid
     */
    function verifySetModeSig(address safe, address signer, uint256 nonce, Mode mode, bytes calldata signature) internal view {
        verifySignature(safe, signer, SET_MODE_METHOD, nonce, abi.encode(mode), signature);
    }

    /**
     * @notice Verifies a signature for updating spending limits
     * @dev Creates and validates an EIP-191 signed message hash
     * @param safe Address of the safe
     * @param signer Address of the signer to verify against
     * @param nonce Transaction nonce for replay protection
     * @param dailyLimitInUsd New daily spending limit in USD
     * @param monthlyLimitInUsd New monthly spending limit in USD
     * @param signature ECDSA signature bytes
     * @custom:throws SignatureUtils.InvalidSignature if the signature is invalid
     */
    function verifyUpdateSpendingLimitSig(address safe, address signer, uint256 nonce, uint256 dailyLimitInUsd, uint256 monthlyLimitInUsd, bytes calldata signature) internal view {
        verifySignature(safe, signer, UPDATE_SPENDING_LIMIT_METHOD, nonce, abi.encode(dailyLimitInUsd, monthlyLimitInUsd), signature);
    }

    /**
     * @notice Verifies a signature for requesting a withdrawal
     * @dev Creates and validates an EIP-191 signed message hash
     * @param safe Address of the safe
     * @param nonce Transaction nonce for replay protection
     * @param tokens Array of token addresses to withdraw
     * @param amounts Array of token amounts to withdraw
     * @param recipient Address to receive the withdrawn tokens
     * @param signers Address of the signers
     * @param signatures ECDSA signatures by signers
     * @custom:throws InvalidSignatures if the signature is invalid
     */
    function verifyRequestWithdrawalSig(address safe, uint256 nonce, address[] calldata tokens, uint256[] calldata amounts, address recipient, address[] calldata signers, bytes[] calldata signatures) internal view {
        bytes32 digestHash = keccak256(abi.encodePacked(REQUEST_WITHDRAWAL_METHOD, block.chainid, safe, nonce, abi.encode(tokens, amounts, recipient))).toEthSignedMessageHash();
        if (!IEtherFiSafe(safe).checkSignatures(digestHash, signers, signatures)) revert InvalidSignatures();
    }

    /**
     * @notice Verifies a signature for cancelling a withdrawal
     * @dev Creates and validates an EIP-191 signed message hash
     * @param safe Address of the safe
     * @param nonce Transaction nonce for replay protection
     * @param signers Address of the signers
     * @param signatures ECDSA signatures by signers
     * @custom:throws InvalidSignatures if the signature is invalid
     */
    function verifyCancelWithdrawalSig(address safe, uint256 nonce, address[] calldata signers, bytes[] calldata signatures) internal view {
        bytes32 digestHash = keccak256(abi.encodePacked(CANCEL_WITHDRAWAL_METHOD, block.chainid, safe, nonce)).toEthSignedMessageHash();
        if (!IEtherFiSafe(safe).checkSignatures(digestHash, signers, signatures)) revert InvalidSignatures();
    }

    /**
     * @notice Verifies a signature for updating cashback split to safe percentage
     * @dev Creates and validates an EIP-191 signed message hash
     * @param safe Address of the safe
     * @param signer Address of the signer to verify against
     * @param nonce Transaction nonce for replay protection
     * @param split Cashback split to safe in bps
     * @param signature ECDSA signature bytes
     * @custom:throws SignatureUtils.InvalidSignature if the signature is invalid
     */
    function verifySetCashbackSplitToSafePercentage(address safe, address signer, uint256 nonce, uint256 split, bytes calldata signature) internal view {
        verifySignature(safe, signer, SET_CASHBACK_SPLIT_TO_SAFE_PERCENTAGE, nonce, abi.encode(split), signature);
    }

    /**
     * @notice Verifies a signature for toggling lend participation (opt in/out of the Aave market)
     * @dev Creates and validates an EIP-191 signed message hash. The requested `enable` flag is bound into
     *      the digest, so an opt-in authorization cannot be replayed as an opt-out (or vice versa).
     * @param safe Address of the safe
     * @param signer Address of the signer to verify against
     * @param nonce Transaction nonce for replay protection
     * @param enable True to enable lend, false to request opting out
     * @param signature ECDSA signature bytes
     * @custom:throws SignatureUtils.InvalidSigner if the signature is invalid
     */
    function verifyToggleLendSig(address safe, address signer, uint256 nonce, bool enable, bytes calldata signature) internal view {
        verifySignature(safe, signer, TOGGLE_LEND_METHOD, nonce, abi.encode(enable), signature);
    }

    /**
     * @notice Verifies the owner quorum authorizing a borrow against the safe's lend-market position
     * @dev The signatures bind the borrow token and USD amount, so neither a compromised backend nor a single
     *      compromised admin can lever a safe up: only a borrow the owner quorum signed can execute
     * @param safe Address of the safe
     * @param nonce Transaction nonce for replay protection
     * @param token Address of the token to borrow
     * @param amountInUsd USD amount to borrow
     * @param signers Address of the signers
     * @param signatures ECDSA signatures by signers
     * @custom:throws InvalidSignatures if the signatures do not meet the owner quorum
     */
    function verifyBorrowSig(address safe, uint256 nonce, address token, uint256 amountInUsd, address[] calldata signers, bytes[] calldata signatures) internal view {
        bytes32 digestHash = keccak256(abi.encodePacked(BORROW_METHOD, block.chainid, safe, nonce, abi.encode(token, amountInUsd))).toEthSignedMessageHash();
        if (!IEtherFiSafe(safe).checkSignatures(digestHash, signers, signatures)) revert InvalidSignatures();
    }
}
"
    },
    "src/libraries/SignatureUtils.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { IERC1271 } from "@openzeppelin/contracts/interfaces/IERC1271.sol";
import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title Library of utilities for making EIP1271-compliant signature checks
 * @author ether.fi
 * @notice Provides functions to verify signatures from both EOAs and smart contracts implementing EIP-1271
 * @dev Implements signature verification following EIP-1271 standard for smart contracts
 * and standard ECDSA verification for EOAs
 */
library SignatureUtils {
    // bytes4(keccak256("isValidSignature(bytes32,bytes)")
    bytes4 internal constant EIP1271_MAGICVALUE = 0x1626ba7e;

    /// @notice Thrown when an EOA signature is invalid
    error InvalidSigner();
    /// @notice Thrown when an ERC1271 contract signature verification fails
    error InvalidERC1271Signer();

    /**
     * @notice Verifies if a signature is valid according to EIP-1271 standards
     * @dev For EOAs, uses ECDSA recovery. For contracts, calls EIP-1271 isValidSignature
     * @param digestHash The hash of the data that was signed
     * @param signer The address that should have signed the data
     * @param signature The signature bytes
     * @custom:security Consider that contract signatures might have different gas costs
     * @custom:warning The isContract check may return false positives during contract construction
     * @custom:throws InvalidSigner If the EOA signature is invalid
     * @custom:throws InvalidERC1271Signer If the contract signature verification fails
     */
    function checkSignature(bytes32 digestHash, address signer, bytes memory signature) internal view {
        if (isContract(signer)) {
            if (IERC1271(signer).isValidSignature(digestHash, signature) != EIP1271_MAGICVALUE) revert InvalidERC1271Signer();
        } else {
            if (ECDSA.recover(digestHash, signature) != signer) revert InvalidSigner();
        }
    }

    /**
     * @notice Returns whether a signature is valid according to EIP-1271 standards
     * @dev Similar to checkSignature_EIP1271 but returns boolean instead of reverting
     * @param digestHash The hash of the data that was signed
     * @param signer The address that should have signed the data
     * @param signature The signature bytes
     * @return bool True if the signature is valid, false otherwise
     * @custom:warning The isContract check may return false positives during contract construction
     */
    function isValidSignature(bytes32 digestHash, address signer, bytes memory signature) internal view returns (bool) {
        if (isContract(signer)) {
            return IERC1271(signer).isValidSignature(digestHash, signature) == EIP1271_MAGICVALUE;
        } else {
            return ECDSA.recover(digestHash, signature) == signer;
        }
    }

    /**
     * @notice Determines if an address is a contract
     * @dev Uses assembly to check if the address has code
     * @param account The address to check
     * @return bool True if the address has code (is a contract), false otherwise
     * @custom:warning This function returns false for contracts during their construction
     */
    function isContract(address account) internal view returns (bool) {
        uint256 size;
        assembly ("memory-safe") {
            size := extcodesize(account)
        }
        return size > 0;
    }
}
"
    },
    "src/libraries/SpendingLimitLib.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

import { TimeLib } from "./TimeLib.sol";

/**
 * @title SpendingLimit
 * @notice Data structure for managing daily and monthly spending limits with time-based renewals
 * @dev Includes current limits, spent amounts, pending limit changes, and renewal timestamps
 */
struct SpendingLimit {
    uint256 dailyLimit; // in USD with 6 decimals
    uint256 monthlyLimit; // in USD with 6 decimals
    uint256 spentToday; // in USD with 6 decimals
    uint256 spentThisMonth; // in USD with 6 decimals
    uint256 newDailyLimit; // in USD with 6 decimals
    uint256 newMonthlyLimit; // in USD with 6 decimals
    uint64 dailyRenewalTimestamp;
    uint64 monthlyRenewalTimestamp;
    uint64 dailyLimitChangeActivationTime;
    uint64 monthlyLimitChangeActivationTime;
    int256 timezoneOffset;
}

/**
 * @title SpendingLimitLib
 * @notice Library for managing spending limits with daily and monthly caps
 * @dev Provides functionality for initializing, updating, and enforcing spending limits
 * @author ether.fi
 */
library SpendingLimitLib {
    using TimeLib for uint256;
    using Math for uint256;

    /**
     * @notice Error thrown when a spend would exceed the daily limit
     */
    error ExceededDailySpendingLimit();

    /**
     * @notice Error thrown when a spend would exceed the monthly limit
     */
    error ExceededMonthlySpendingLimit();

    /**
     * @notice Error thrown when daily limit is set higher than monthly limit
     */
    error DailyLimitCannotBeGreaterThanMonthlyLimit();

    /**
     * @notice Error thrown when timezone offset is invalid
     */
    error InvalidTimezoneOffset();

    /**
     * @notice Initializes a new SpendingLimit with daily and monthly caps
     * @dev Sets up initial renewal timestamps based on current time and timezone offset
     * @param limit Storage reference to the SpendingLimit to initialize
     * @param dailyLimit Maximum amount that can be spent in a day (USD with 6 decimals)
     * @param monthlyLimit Maximum amount that can be spent in a month (USD with 6 decimals)
     * @param timezoneOffset User's timezone offset in seconds
     * @return The initialized SpendingLimit
     * @custom:throws DailyLimitCannotBeGreaterThanMonthlyLimit if daily limit exceeds monthly limit
     * @custom:throws InvalidTimezoneOffset if timezone offset is outside valid range
     */
    function initialize(SpendingLimit storage limit, uint256 dailyLimit, uint256 monthlyLimit, int256 timezoneOffset) internal sanity(dailyLimit, monthlyLimit) returns (SpendingLimit memory) {
        if (timezoneOffset > 24 * 60 * 60 || timezoneOffset < -24 * 60 * 60) revert InvalidTimezoneOffset();
        limit.dailyLimit = dailyLimit;
        limit.monthlyLimit = monthlyLimit;
        limit.timezoneOffset = timezoneOffset;
        limit.dailyRenewalTimestamp = block.timestamp.getStartOfNextDay(limit.timezoneOffset);
        limit.monthlyRenewalTimestamp = block.timestamp.getStartOfNextMonth(limit.timezoneOffset);

        return limit;
    }

    /**
     * @notice Updates storage with the current limit state
     * @dev Refreshes all fields of the limit struct with current values
     * @param limit Storage reference to the SpendingLimit to update
     */
    function currentLimit(SpendingLimit storage limit) internal {
        SpendingLimit memory finalLimit = getCurrentLimit(limit);

        limit.dailyLimit = finalLimit.dailyLimit;
        limit.monthlyLimit = finalLimit.monthlyLimit;
        limit.spentToday = finalLimit.spentToday;
        limit.spentThisMonth = finalLimit.spentThisMonth;
        limit.newDailyLimit = finalLimit.newDailyLimit;
        limit.newMonthlyLimit = finalLimit.newMonthlyLimit;
        limit.dailyRenewalTimestamp = finalLimit.dailyRenewalTimestamp;
        limit.monthlyRenewalTimestamp = finalLimit.monthlyRenewalTimestamp;
        limit.dailyLimitChangeActivationTime = finalLimit.dailyLimitChangeActivationTime;
        limit.monthlyLimitChangeActivationTime = finalLimit.monthlyLimitChangeActivationTime;
    }

    /**
     * @notice Records a spend against the daily and monthly limits
     * @dev Updates current limits first, then applies the spend if within limits
     * @param limit Storage reference to the SpendingLimit
     * @param amount Amount to spend (USD with 6 decimals)
     * @custom:throws ExceededDailySpendingLimit if spend would exceed daily limit
     * @custom:throws ExceededMonthlySpendingLimit if spend would exceed monthly limit
     */
    function spend(SpendingLimit storage limit, uint256 amount) internal {
        currentLimit(limit);

        if (limit.spentToday + amount > limit.dailyLimit) revert ExceededDailySpendingLimit();
        if (limit.spentThisMonth + amount > limit.monthlyLimit) revert ExceededMonthlySpendingLimit();

        limit.spentToday += amount;
        limit.spentThisMonth += amount;
    }

    /**
     * @notice Updates spending limits with optional delay for decreases
     * @dev Immediate increases, delayed decreases with activation timestamp
     * @param limit Storage reference to the SpendingLimit
     * @param newDailyLimit New daily spending limit (USD with 6 decimals)
     * @param newMonthlyLimit New monthly spending limit (USD with 6 decimals)
     * @param delay Seconds to delay limit decreases (0 for immediate)
     * @return Original limit before changes
     * @return Updated limit after changes
     * @custom:throws DailyLimitCannotBeGreaterThanMonthlyLimit if daily limit exceeds monthly limit
     */
    function updateSpendingLimit(SpendingLimit storage limit, uint256 newDailyLimit, uint256 newMonthlyLimit, uint64 delay) internal sanity(newDailyLimit, newMonthlyLimit) returns (SpendingLimit memory, SpendingLimit memory) {
        currentLimit(limit);
        SpendingLimit memory oldLimit = limit;

        if (newDailyLimit < limit.dailyLimit) {
            limit.newDailyLimit = newDailyLimit;
            limit.dailyLimitChangeActivationTime = uint64(block.timestamp) + delay;
        } else {
            limit.dailyLimit = newDailyLimit;
            limit.newDailyLimit = 0;
            limit.dailyLimitChangeActivationTime = 0;
        }

        if (newMonthlyLimit < limit.monthlyLimit) {
            limit.newMonthlyLimit = newMonthlyLimit;
            limit.monthlyLimitChangeActivationTime = uint64(block.timestamp) + delay;
        } else {
            limit.monthlyLimit = newMonthlyLimit;
            limit.newMonthlyLimit = 0;
            limit.monthlyLimitChangeActivationTime = 0;
        }

        return (oldLimit, limit);
    }

    /**
     * @notice Calculates the maximum amount that can be spent right now
     * @dev Considers both daily and monthly limits, returning the lower of the two remaining amounts
     * @param limit Memory copy of the SpendingLimit
     * @return Maximum spendable amount in USD with 6 decimals
     */
    function maxCanSpend(SpendingLimit memory limit) internal view returns (uint256) {
        limit = getCurrentLimit(limit);
        bool usingIncomingDailyLimit = false;
        bool usingIncomingMonthlyLimit = false;
        uint256 applicableDailyLimit = limit.dailyLimit;
        uint256 applicableMonthlyLimit = limit.monthlyLimit;

        if (limit.dailyLimitChangeActivationTime != 0) {
            applicableDailyLimit = limit.newDailyLimit;
            usingIncomingDailyLimit = true;
        }
        if (limit.monthlyLimitChangeActivationTime != 0) {
            applicableMonthlyLimit = limit.newMonthlyLimit;
            usingIncomingMonthlyLimit = true;
        }

        if (limit.spentToday > applicableDailyLimit) return 0;
        if (limit.spentThisMonth > applicableMonthlyLimit) return 0;

        return Math.min(applicableDailyLimit - limit.spentToday, applicableMonthlyLimit - limit.spentThisMonth);
    }

    /**
     * @notice Checks if a specific amount can be spent
     * @dev Considers both daily and monthly limits, including pending limit changes
     * @param limit Memory copy of the SpendingLimit
     * @param amount Amount to check if spendable (USD with 6 decimals)
     * @return canSpend Boolean indicating if the amount can be spent
     * @return message Error message if amount cannot be spent
     */
    function canSpend(SpendingLimit memory limit, uint256 amount) internal view returns (bool, string memory) {
        limit = getCurrentLimit(limit);

        bool usingIncomingDailyLimit = false;
        bool usingIncomingMonthlyLimit = false;
        uint256 applicableDailyLimit = limit.dailyLimit;
        uint256 applicableMonthlyLimit = limit.monthlyLimit;

        if (limit.dailyLimitChangeActivationTime != 0) {
            applicableDailyLimit = limit.newDailyLimit;
            usingIncomingDailyLimit = true;
        }
        if (limit.monthlyLimitChangeActivationTime != 0) {
            applicableMonthlyLimit = limit.newMonthlyLimit;
            usingIncomingMonthlyLimit = true;
        }

        if (limit.spentToday > applicableDailyLimit) {
            if (usingIncomingDailyLimit) return (false, "Incoming daily spending limit already exhausted");
            else return (false, "Daily spending limit already exhausted");
        }

        if (limit.spentThisMonth > applicableMonthlyLimit) {
            if (usingIncomingMonthlyLimit) return (false, "Incoming monthly spending limit already exhausted");
            else return (false, "Monthly spending limit already exhausted");
        }

        uint256 availableDaily = applicableDailyLimit - limit.spentToday;
        uint256 availableMonthly = applicableMonthlyLimit - limit.spentThisMonth;

        if (amount > availableDaily) {
            if (usingIncomingDailyLimit) return (false, "Incoming daily available spending limit less than amount requested");
            return (false, "Daily available spending limit less than amount requested");
        }

        if (amount > availableMonthly) {
            if (usingIncomingMonthlyLimit) return (false, "Incoming monthly available spending limit less than amount requested");
            return (false, "Monthly available spending limit less than amount requested");
        }

        return (true, "");
    }

    /**
     * @notice Gets the current limit state with all time-based updates applied
     * @dev Applies pending limit changes and resets counters on renewal timestamps
     * @param limit Memory copy of the SpendingLimit
     * @return Updated SpendingLimit reflecting current state
     */
    function getCurrentLimit(SpendingLimit memory limit) internal view returns (SpendingLimit memory) {
        if (limit.dailyLimitChangeActivationTime != 0 && block.timestamp > limit.dailyLimitChangeActivationTime) {
            limit.dailyLimit = limit.newDailyLimit;
            limit.newDailyLimit = 0;
            limit.dailyLimitChangeActivationTime = 0;
        }

        if (limit.monthlyLimitChangeActivationTime != 0 && block.timestamp > limit.monthlyLimitChangeActivationTime) {
            limit.monthlyLimit = limit.newMonthlyLimit;
            limit.newMonthlyLimit = 0;
            limit.monthlyLimitChangeActivationTime = 0;
        }

        if (block.timestamp > limit.dailyRenewalTimestamp) {
            limit.spentToday = 0;
            limit.dailyRenewalTimestamp = getFinalDailyRenewalTimestamp(limit.dailyRenewalTimestamp, limit.timezoneOffset);
        }

        if (block.timestamp > limit.monthlyRenewalTimestamp) {
            limit.spentThisMonth = 0;
            limit.monthlyRenewalTimestamp = getFinalMonthlyRenewalTimestamp(limit.monthlyRenewalTimestamp, limit.timezoneOffset);
        }

        return limit;
    }

    /**
     * @notice Calculates the next valid daily renewal timestamp
     * @dev Handles cases where multiple renewal periods have elapsed
     * @param renewalTimestamp Current renewal timestamp
     * @param timezoneOffset User's timezone offset in seconds
     * @return Next valid daily renewal timestamp
     */
    function getFinalDailyRenewalTimestamp(uint64 renewalTimestamp, int256 timezoneOffset) internal view returns (uint64) {
        do {
            renewalTimestamp = uint256(renewalTimestamp).getStartOfNextDay(timezoneOffset);
        } while (block.timestamp > renewalTimestamp);

        return renewalTimestamp;
    }

    /**
     * @notice Calculates the next valid monthly renewal timestamp
     * @dev Handles cases where multiple renewal periods have elapsed
     * @param renewalTimestamp Current renewal timestamp
     * @param timezoneOffset User's timezone offset in seconds
     * @return Next valid monthly renewal timestamp
     */
    function getFinalMonthlyRenewalTimestamp(uint64 renewalTimestamp, int256 timezoneOffset) internal view returns (uint64) {
        do {
            renewalTimestamp = uint256(renewalTimestamp).getStartOfNextMonth(timezoneOffset);
        } while (block.timestamp > renewalTimestamp);

        return renewalTimestamp;
    }

    /**
     * @dev Modifier to ensure daily limit is not greater than monthly limit
     * @param dailyLimit Daily spending limit to validate
     * @param monthlyLimit Monthly spending limit to validate
     * @custom:throws DailyLimitCannotBeGreaterThanMonthlyLimit if daily limit exceeds monthly limit
     */
    modifier sanity(uint256 dailyLimit, uint256 monthlyLimit) {
        if (dailyLimit > monthlyLimit) revert DailyLimitCannotBeGreaterThanMonthlyLimit();
        _;
    }
}
"
    },
    "src/utils/UpgradeableProxy.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { UUPSUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import { PausableUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import { ReentrancyGuardTransientUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardTransientUpgradeable.sol";

import { IRoleRegistry } from "../interfaces/IRoleRegistry.sol";

/**
 * @title UpgradeableProxy
 * @author ether.fi
 * @notice An UpgradeableProxy contract which can be upgraded by RoleRegistry contract
 */
contract UpgradeableProxy is UUPSUpgradeable, PausableUpgradeable, ReentrancyGuardTransientUpgradeable {
    /// @custom:storage-location erc7201:etherfi.storage.UpgradeableProxy
    struct UpgradeableProxyStorage {
        /// @notice Reference to the role registry contract for access control
        IRoleRegistry roleRegistry;
    }

    // keccak256(abi.encode(uint256(keccak256("etherfi.storage.UpgradeableProxy")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant UpgradeableProxyStorageLocation = 0xa5586bb7fe6c4d1a576fc53fefe6d5915940638d338769f6905020734977f500;

    /// @notice Error thrown when caller is unauthorized to perform an operation
    error Unauthorized();

    /// @notice Error thrown when caller is not the role registry owner
    error OnlyRoleRegistryOwner();


    /**
     * @notice Returns the address of the Role Registry contract
     * @return roleRegistry Reference to the role registry contract
     */
    function roleRegistry() public view returns (IRoleRegistry) {
        UpgradeableProxyStorage storage $ = _getUpgradeableProxyStorage();
        return $.roleRegistry;
    }

    /**
     * @dev Initializes the contract with Role Registry
     * @param _roleRegistry Address of the role registry contract
     */
    function __UpgradeableProxy_init(address _roleRegistry) internal onlyInitializing {
        UpgradeableProxyStorage storage $ = _getUpgradeableProxyStorage();
        $.roleRegistry = IRoleRegistry(_roleRegistry);

        __ReentrancyGuardTransient_init();
        __Pausable_init_unchained();
    }

    /**
     * @dev Returns the storage struct from the specified storage slot
     * @return $ Reference to the UpgradeableProxyStorage struct
     */
    function _getUpgradeableProxyStorage() internal pure returns (UpgradeableProxyStorage storage $) {
        assembly {
            $.slot := UpgradeableProxyStorageLocation
        }
    }

    /**
     * @dev Updates the role registry contract address
     * @param _roleRegistry The address of the new role registry contract
     * @custom:security This is a critical function that updates access control
     */
    function _setRoleRegistry(address _roleRegistry) internal {
        UpgradeableProxyStorage storage $ = _getUpgradeableProxyStorage();
        $.roleRegistry = IRoleRegistry(_roleRegistry);
    }

    /**
     * @dev Ensures only authorized upgraders can upgrade the contract
     * @param newImplementation Address of the new implementation contract
     */
    function _authorizeUpgrade(address newImplementation) internal view override {
        UpgradeableProxyStorage storage $ = _getUpgradeableProxyStorage();
        $.roleRegistry.onlyUpgrader(msg.sender);

        // Silence compiler warning on unused variables.
        newImplementation = newImplementation;
    }

    /**
     * @notice Pauses the contract
     * @dev Only callable by accounts with the pauser role
     */
    function pause() external {
        roleRegistry().onlyPauser(msg.sender);
        _pause();
    }

    /**
     * @notice Unpauses the contract
     * @dev Only callable by accounts with the unpauser role
     */
    function unpause() external {
        roleRegistry().onlyUnpauser(msg.sender);
        _unpause();
    }

    /**
     * @dev Modifier to restrict access to specific roles
     * @param role Role identifier
     */
    modifier onlyRole(bytes32 role) {
        if (!roleRegistry().hasRole(role, msg.sender)) revert Unauthorized();
        _;
    }

    /**
     * @dev Modifier to restrict access to owner of the role registry
     */
    modifier onlyRoleRegistryOwner() {
        if (roleRegistry().owner() != msg.sender) revert OnlyRoleRegistryOwner();
        _;
    }

    /**
     * @dev Modifier to restrict access to holders of the registry's ADMIN_ROLE
     */
    modifier onlyAdmin() {
        roleRegistry().onlyAdmin(msg.sender);
        _;
    }

    /**
     * @dev Modifier to restrict access to holders of the registry's ADMIN_TIMELOCK_ROLE
     */
    modifier onlyAdminTimelock() {
        roleRegistry().onlyAdminTimelock(msg.sender);
        _;
    }
}
"
    },
    "src/modules/ModuleBase.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { IERC20 } from "@openzeppelin/contracts/interfaces/IERC20.sol";

import { IEtherFiDataProvider } from "../interfaces/IEtherFiDataProvider.sol";
import { IEtherFiSafe } from "../interfaces/IEtherFiSafe.sol";
import { SignatureUtils } from "../libraries/SignatureUtils.sol";
import { Constants } from "../utils/Constants.sol";

/**
 * @title ModuleBase
 * @author ether.fi
 * @notice Base contract for implementing modules with admin functionality
 * @dev Provides common functionality for modules including admin management and signature verification
 *      Uses ERC-7201 for namespace storage pattern
 */
contract ModuleBase is Constants {
    using SignatureUtils for bytes32;

    IEtherFiDataProvider public immutable etherFiDataProvider;

    /// @notice Throws when the msg.sender is not an admin to the safe
    error OnlySafeAdmin();
    /// @notice Thrown when the input is invalid
    error InvalidInput();
    /// @notice Thrown when the signature verification fails
    error InvalidSignature();
    /// @notice Thrown when there is an array length mismatch
    error ArrayLengthMismatch();
    /// @notice Thrown when the caller is not an EtherFi Safe
    error OnlyEtherFiSafe();
    /// @notice Thrown when insufficient amount is available for use from the safe
    error AmountNotAvailable();

    /// @custom:storage-location erc7201:etherfi.storage.ModuleBaseStorage
    struct ModuleBaseStorage {
        /// @notice Mapping of Safe addresses to their nonces for replay protection
        mapping(address safe => uint256 nonce) nonces;
    }

    // keccak256(abi.encode(uint256(keccak256("etherfi.storage.ModuleBaseStorage")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant ModuleBaseStorageLocation = 0x9425b2e03e09da4c20ff7a465da264f7a02bf7079e1dbb47fce0436e1d206d00;

    constructor(address _etherFiDataProvider) {
        if (_etherFiDataProvider == address(0)) revert InvalidInput();
        etherFiDataProvider = IEtherFiDataProvider(_etherFiDataProvider);
    }

    /**
     * @dev Returns the storage struct from the specified storage slot
     * @return $ Reference to the ModuleBaseStorage struct
     */
    function _getModuleBaseStorage() internal pure returns (ModuleBaseStorage storage $) {
        assembly {
            $.slot := ModuleBaseStorageLocation
        }
    }

    /**
     * @notice Returns the current nonce for a Safe
     * @param safe The Safe address to query
     * @return Current nonce value
     * @dev Nonces are used to prevent signature replay attacks
     */
    function getNonce(address safe) public view returns (uint256) {
        return _getModuleBaseStorage().nonces[safe];
    }

    /**
     * @dev Uses and increments the nonce for a Safe
     * @param safe The Safe address
     * @return The nonce value before incrementing
     */
    function _useNonce(address safe) internal returns (uint256) {
        ModuleBaseStorage storage $ = _getModuleBaseStorage();

        unchecked {
            return $.nonces[safe]++;
        }
    }

    /**
     * @dev Verifies if a signature is valid and made by an admin of the safe
     * @param digestHash The message hash that was signed
     * @param signer The address that supposedly signed the message
     * @param signature The signature to verify
     * @custom:throws SignerIsNotAnAdmin If the signer is not an admin of the Safe
     * @custom:throws InvalidSignature If the signature is invalid
     */
    function _verifyAdminSig(bytes32 digestHash, address signer, bytes calldata signature) internal view {
        if (!digestHash.isValidSignature(signer, signature)) revert InvalidSignature();
    }

    /**
     * @dev Ensures that the caller is an admin for the specified Safe
     * @param safe The Safe address to check admin status for
     */
    modifier onlySafeAdmin(address safe, address account) {
        if (!IEtherFiSafe(safe).isAdmin(account)) revert OnlySafeAdmin();
        _;
    }

    /**
     * @dev Ensures that the account is an instance of the deployed EtherfiSafe
     * @param account The account address to check
     */
    modifier onlyEtherFiSafe(address account) {
        if (!etherFiDataProvider.isEtherFiSafe(account)) revert OnlyEtherFiSafe();
        _;
    }

    /**
     * @notice Sets up a new Safe's Module with initial configuration
     * @dev Override this function to configure a module initially
     * @param data The encoded initialization data
